# Secret Manager name -> stack/.env variable -> where the value comes from.
#   gen:hex:N  random N bytes as hex     gen:sk  "sk-" + 32 random bytes (LiteLLM wants the prefix)
#   gen:pass   password for Chatwoot's policy (upper, lower, digit, special)
#   gen:pfx:P:N  the prefix P + N random bytes as hex (Langfuse keys: pk-lf-, sk-lf-)
#   env:VAR    copied once from ./.env of this checkout (deploy/secrets.sh import)
#   manual     set by hand: printf %s 'VALUE' | gcloud secrets versions add NAME --data-file=- --project=...
# The mentor created seven names on the project. Since 26.11 Telegram goes through the userbot only:
# telegram-bot-token was deleted, webhook-secret (the Bot API webhook) stays in Secret Manager unread.
# The rest are created by deploy/secrets.sh init.
chatwoot-secret-key-base  SECRET_KEY_BASE           gen:hex:64
db-password               CW_POSTGRES_PASSWORD      gen:hex:24
meta-wa-verify-token      META_WA_VERIFY_TOKEN      gen:hex:24
meta-wa-access-token      META_WA_ACCESS_TOKEN      manual
meta-app-secret           META_APP_SECRET           manual
redis-password            REDIS_PASSWORD            gen:hex:24
agents-db-password        AGENTS_POSTGRES_PASSWORD  gen:hex:24
agents-app-db-password    AGENTS_APP_DB_PASSWORD    gen:hex:24
agents-jwt-secret         JWT_SECRET                gen:hex:32
agents-mcp-jwt-secret     MCP_JWT_SECRET            gen:hex:32
agents-encryption-key     ENCRYPTION_KEY            gen:hex:32
tickets-api-token         TICKETS_API_TOKEN         gen:hex:32
stt-api-token             STT_API_TOKEN             gen:hex:32
litellm-master-key        LITELLM_MASTER_KEY        gen:sk
chatwoot-admin-password   CW_ADMIN_PASSWORD         gen:pass
agents-admin-password     AGENTS_ADMIN_PASSWORD     gen:pass
tg-api-id                 TG_API_ID                 env:TG_API_ID
tg-api-hash               TG_API_HASH               env:TG_API_HASH
# Platform (stack/platform.yml): Twenty, Hatchet, Langfuse.
platform-pg-password      PLATFORM_PG_PASSWORD      gen:hex:24
platform-redis-password   PLATFORM_REDIS_PASSWORD   gen:hex:24
langfuse-db-password      LANGFUSE_DB_PASSWORD      gen:hex:24
twenty-db-password        TWENTY_DB_PASSWORD        gen:hex:24
hatchet-db-password       HATCHET_DB_PASSWORD       gen:hex:24
clickhouse-password       CLICKHOUSE_PASSWORD       gen:hex:24
minio-password            MINIO_PASSWORD            gen:hex:24
langfuse-nextauth-secret  LANGFUSE_NEXTAUTH_SECRET  gen:hex:32
langfuse-salt             LANGFUSE_SALT             gen:hex:32
langfuse-encryption-key   LANGFUSE_ENCRYPTION_KEY   gen:hex:32
langfuse-public-key       LANGFUSE_PUBLIC_KEY       gen:pfx:pk-lf-:16
langfuse-secret-key       LANGFUSE_SECRET_KEY       gen:pfx:sk-lf-:24
langfuse-admin-password   LANGFUSE_ADMIN_PASSWORD   gen:pass
twenty-encryption-key     TWENTY_ENCRYPTION_KEY     gen:hex:32
twenty-app-secret         TWENTY_APP_SECRET         gen:hex:32
hatchet-admin-password    HATCHET_ADMIN_PASSWORD    gen:pass
twenty-admin-password     TWENTY_ADMIN_PASSWORD     gen:pass
orchestrator-token        ORCH_TOKEN                gen:hex:32
